 var ts=String(Math.floor(Date.now()/1000));
 var q="bookId="+bid+"&user_id="+UID+"&timestamp="+ts+"&sign="+SQ_md5(String(bid)+ts+UID+KEY);
 var raw="";
 try{raw=SQ_webGet(Jv,"https://content.shuqireader.com/openapi/book/chapterlist?shuqi_h5=205&platform=0&"+q);}catch(e){}
 if(!raw||raw.length<200){try{raw=SQ_webGet(Jv,"https://ocean.shuqireader.com/api/bcspub/qswebapi/book/chapterlist?_=&"+q);}catch(e2){}}
 var d={};try{d=JSON.parse(raw);}catch(e3){return [];}
 if(String(d.state)!=="200"&&String(d.status)!=="200")return [];
 var dt=d.data||{},cls=dt.chapterList||[],vols=[],i,j;
 for(i=0;i<cls.length;i++){
  var v=cls[i]||{},a=v.volumeList||v.chapterList||v.chapter||[],rows=[];
  for(j=0;j<a.length;j++){
