 if(h.length>5000&&h.indexOf("cid=")>=0){
  var rows=SQ_h5Rows(h,bid,S);
  if(rows.length){
   var marks=[],vm=/<div class="vol_name"[^>]*>\s*<span>([\s\S]*?)<\/span>/g,mm;
   while((mm=vm.exec(h))!==null)marks.push({pos:mm.index,name:SQ_plain(mm[1])});
   var out=[],k,vi,fk,firstSet={};
   if(marks.length>=2){
    for(vi=0;vi<marks.length;vi++){
     fk=-1;
     for(k=0;k<rows.length;k++)if(rows[k].pos>=marks[vi].pos&&(vi+1>=marks.length||rows[k].pos<marks[vi+1].pos)){fk=k;break;}
     if(fk>=0&&marks[vi].name)firstSet[fk]=marks[vi].name;
    }
   }
   for(k=0;k<rows.length;k++){
    var t=rows[k].title;
    if(firstSet[k])t=SQ_volMark(firstSet[k],t);
