 for(i=0;i<SQ_ALL_LINES.length;i++){
  var host=SQ_ALL_LINES[i];
  var isCdn=SQ_CDN_ALT.indexOf(host)>=0;
  var probe=isCdn?host+"/httpserver/filecache/get_book_content_34078_2180322_3111111111_0_0.html"
                  :host+"/ranklist?rank=boyClick";
  var t0=Date.now(),ok=false,ms=0;
  try{var h=SQ_webGet(Jv,probe);
   ms=Date.now()-t0;
   ok=isCdn?(h.indexOf("success_jsonpCallback")>=0&&h.indexOf("\\u3000")>=0)
           :(h.length>5000&&h.indexOf("ranklist-ul")>=0&&h.indexOf("访问被拒绝")<0);
  }catch(e){ms=Date.now()-t0;}
  var st=ok?ms+"ms":"超时/不支持";
