ruleToc.chapterList:
@js:
var chapters = [];
var domain = (baseUrl.match(/^https?:\/\/[^\/]+/) || [''])[0];
var html = src || result || '';

function toAbs(u) { return u.indexOf('http') < 0 ? domain + (u.indexOf('/') === 0 ? '' : '/') + u : u; }
function grabUl(ulHtml) {
    var out = [];
    var re = /<li><a href="([^"]+)"[^>]*>([\s\S]*?)<\/a><\/li>/g;
    var m;
    while ((m = re.exec(ulHtml))) {
        var name = m[2].replace(/<[^>]+>/g, '').replace(/^\s+|\s+$/g, '');
        if (name && m[1]) out.push({text: name, href: m[1]});
    }
    return out;
}
function selectPages(h) {
    var sel = h.match(/<select[^>]*>([\s\S]*?)<\/select>/);
    var urls = [];
    if (sel) {
        var re = /<option[^>]*value="([^"]+)"/g, om;
        while ((om = re.exec(sel[1]))) { var u = toAbs(om[1]); if (urls.indexOf(u) < 0) urls.push(u); }
    }
    return urls;
}

// 1. 从详情页 章节列表 区块抓取第1-100章(排除最新章节干扰)
var cs = html.match(/<h3[^>]*>章节列表[\s\S]*?<ul[^>]*class="chapter-list"[^>]*>([\s\S]*?)<\/ul>/);
if (cs) chapters = chapters.concat(grabUl(cs[1]));

// 2. 找到第一个 index 页
var firstIndex = html.match(/href="([^"]*index_\d+\.html)"/);
var pages = [];
if (firstIndex) {
    var idxHtml = java.ajax(toAbs(firstIndex[1]));
    pages = selectPages(idxHtml);
    var u2 = idxHtml.match(/<ul[^>]*class="chapter-list"[^>]*>([\s\S]*?)<\/ul>/);
    if (u2) chapters = chapters.concat(grabUl(u2[1]));
}

// 3. 抓取其余 index 页
for (var i = 0; i < pages.length; i++) {
    if (/index_\d+\.html/.test(pages[i])) {
        if (firstIndex && pages[i] === toAbs(firstIndex[1])) continue;
        var h = java.ajax(pages[i]);
        var u3 = h.match(/<ul[^>]*class="chapter-list"[^>]*>([\s\S]*?)<\/ul>/);
        if (u3) chapters = chapters.concat(grabUl(u3[1]));
    }
}

// 4. 按 href 去重(保留首次出现)
var seen = {}; var out = [];
for (var k = 0; k < chapters.length; k++) {
    if (!seen[chapters[k].href]) { seen[chapters[k].href] = true; out.push(chapters[k]); }
}
out;

jsLib:
var hosts = [
    "https://www.suduguu.com",
    "https://shudugu.org",
    "https://sudugu520.com"
];

function getHosts() {
    return hosts;
}

function getServerHost() {
    var source = this.source;
    try {
        var config = JSON.parse(source.getVariable());
        if (config && config[0] && config[0].host) {
            return config[0].host;
        }
        return getHosts()[0];
    } catch (e) {
        return getHosts()[0];
    }
}

function getConfig() {
    var source = this.source;
    try {
        var configStr = source.getVariable();
        if (!configStr || configStr.trim() === "") {
            return { host: getHosts()[0] };
        }
        var config = JSON.parse(configStr);
        if (!config || !config.join || config.length === 0) {
            return { host: getHosts()[0] };
        }
        return config[0] || { host: getHosts()[0] };
    } catch (e) {
        return { host: getHosts()[0] };
    }
}

function setConfig(key, value) {
    var source = this.source;
    try {
        var config = getConfig.call(this);
        config[key] = value;
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

function setConfigs(obj) {
    var source = this.source;
    try {
        var config = getConfig.call(this);
        for (var k in obj) {
            if (obj.hasOwnProperty(k)) {
                config[k] = obj[k];
            }
        }
        source.setVariable(JSON.stringify([config]));
        return true;
    } catch (e) {
        return false;
    }
}

function checkConnectivity(host) {
    var timeout = 5000;
    var socket = null;
    try {
        var start = new Date().getTime();
        var jUrl = new Packages.java.net.URL(host);
        var hostname = jUrl.getHost();
        var port = jUrl.getPort();
        if (port === -1) { port = jUrl.getDefaultPort(); }
        socket = new Packages.java.net.Socket();
        var addr = new Packages.java.net.InetSocketAddress(hostname, port);
        socket.connect(addr, timeout);
        var latency = new Date().getTime() - start;
        return {ok: true, latency: latency};
    } catch (e) {
        return {ok: false, latency: -1, err: String(e)};
    } finally {
        try { if (socket !== null) { socket.close(); } } catch (e2) {}
    }
}

function autoSelectHost() {
    var allHosts = getHosts();
    var details = [];
    var best = null;
    var bestLatency = -1;
    for (var i = 0; i < allHosts.length; i++) {
        var r = checkConnectivity.call(this, allHosts[i]);
        r.host = allHosts[i];
        details.push(r);
        if (r.ok && (bestLatency < 0 || r.latency < bestLatency)) {
            best = allHosts[i];
            bestLatency = r.latency;
        }
    }
    if (best !== null) {
        setConfig.call(this, 'host', best);
    }
    return {success: best !== null, host: best, details: details};
}

